void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv0 = (fragCoord.xy - 0.5*iResolution.xy) / iResolution.y;

    float nTiles = 3.;

    vec2 uv = fract(uv0*nTiles)-0.5;
    vec2 id = floor(uv0 * nTiles); // Unique ID for each tile

    float shapeScale = 0.5;
    uv *= 1./shapeScale;

    float blur = 1./iResolution.y*nTiles;

    vec3 col = vec3(0.);//0.5 + 0.5*cos(iTime+uv0.xyy+vec3(1,2,3));

    float d = sdStar(uv, 1., 8., 0.9);
    col += vec3(1.,0.,0.)*sin(iTime+0.0) * ( 1.-smoothstep(-blur,blur, d));
    col += vec3(0.,1.,0.)*sin(iTime+1.5) * smoothstep(-blur,blur, d);

    d = sdOctogon(uv, 0.7);
    col += vec3(0.,0.,1.)*sin(iTime+1.) * ( 1.-smoothstep(-blur,blur, d) );

    d = sdStar(uv, 0.7, 8.*2., 0.9);
    col += vec3(1.,0.,0.)*sin(iTime+0.5) * ( 1.-smoothstep(-blur,blur, d) );

    float lineScale = 2.;
    float lines = step(0.5, abs(fract(uv.x*lineScale - 0.25)));
    lines += step(0.5, abs(fract(uv.y*lineScale - 0.25)));

    col -= step(2., lines) * vec3(0.,0.5,1.);

    fragColor = vec4(col,1.0);
}

